	"That advert is not on the board.": "Esse anúncio não está no painel.",
	"All simulated ads": "Todos os anúncios simulados",
	"Back to the lobby": "Voltar ao átrio",
	"Put a real name here": "Ponha aqui um nome verdadeiro",
	"mx-auto max-w-5xl px-4 py-10 sm:px-6": "mx-auto max-w-5xl px-4 py-10 sm:px-6",
